import { setupWorker } from "msw/browser";
import { handlers } from "./handlers";

// 옵션은 index.js에서 주입
export const worker = setupWorker(...handlers);
// apiPath가 실제로 뭘 내는지 체크
(async () => {
  const { apiPath } = await import("/src/api/config.js");
  const u = apiPath("/order/orderlist");
  console.log("apiPath('/order/orderlist') =", u);
  const r = await fetch(u).catch(e => e);
  console.log("fetch status =", r?.status, "url =", r?.url || "(network error)");
})();
